pub type Color = { r: Int; g: Int; b: Int; } derive[Eq]

fn is_grayscale(c: &Color) -> Bool {
  return c.r == c.g && c.g == c.b;
}

fn main() -> Int {
  let white = Color{ r: 255, g: 255, b: 255 };
  let black = Color{ r: 0, g: 0, b: 0 };
  if white == black {
    return 1;
  }
  return 0;
}
